  "question": "What is the sum of the tariff percentage on H200s and the number of Exchange Act sections cited in the In Re NVIDIA Securities Litigation?",
  "answer": "28 (25% tariff + 3 sections: 14(a), 10(b), 20(a))",
  "quote_a": "any H200 shipped under the new licensing program will be subject to a 25% tariff upon importation into the United States.",
  "quote_b": "violations of Sections 14(a), 10(b), and 20(a) of the Exchange Act based on the dissemination of allegedly false, and misleading statements"
}
